        let mut ops = Vec::new();
        if self.anchor.is_none() || (now >= self.active_until && self.active.is_none()) {
            self.release_active(&mut ops);
            self.anchor = Some(now);
            self.cycle_start = now;
            self.next_event = 0;
        }
        self.active_until = now + self.tail_beats;
        self.channel = channel;
        LaneOutput {
            ops,
            ..Default::default()
